import{z as n,x as l,o as B,c as D,q as t,j as s,D as A,d as e,s as o,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"中断与驱动的骨架","description":"","frontmatter":{"title":"中断与驱动的骨架","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/osk-interrupt-drivers.md","filePath":"cs/osk-interrupt-drivers.md","lastUpdated":1791413859000}'),p={name:"cs/osk-interrupt-drivers.md"};function d(C,E,u,m,c,h){const r=l("Mermaid");return B(),D("div",null,[E[2]||(E[2]=t('<h1 id="中断与驱动的骨架" tabindex="-1">中断与驱动的骨架 <a class="header-anchor" href="#中断与驱动的骨架" aria-label="Permalink to &quot;中断与驱动的骨架&quot;">​</a></h1><div class="epigraph"><p>驱动不是「操作设备的代码」，而是把一个说方言的设备注册成内核已有对象的那段胶水。</p><footer>—— 据 Tanenbaum and Bos, Modern Operating Systems；Arpaci-Dusseau, OSTEP 整理</footer></div><p><a href="/cs/osk-syscall-path">上一课</a>修好了同步进入内核的路；设备不等调用——异步进入内核的路是本课。<a href="/cs/hardirq-softirq">硬中断与软中断</a>、<a href="/cs/interrupt-bottom-half">中断下半部</a>已给上下半部的分工，<a href="/cs/apic-interrupt-routing">APIC 与中断路由</a>给了硬件侧的路由。缺口是把它们装配成一个能跑的驱动骨架：一条中断线从设备到处理函数走哪些层，probe 到 remove 之间都发生什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>内核里有成百上千种设备。若每种设备自带一套中断、缓冲与注册方式，块、网络、字符这些子系统就没法统一调度它们，写一个新设备就要重造一遍全部接缝。实现要回答三件事：设备的「存在」如何变成内核对象；中断到来时，通用层如何在一微秒内找到正确的处理函数；为什么处理函数里不许睡眠。不这么做会错在哪：在中断上下文里调用一个可能阻塞的函数——调度器不在中断里运行，没有人能把它换下去，那颗 CPU 就挂死在中途，往往表现为偶发的整机卡顿而不是清晰的崩溃。</p><p><span class="marginnote">常见误区：初学者容易以为在中断处理函数里调用会阻塞的函数顶多「等一等」。实际上中断上下文里没有进程身份，调度器管不到你——没有任何人能把你换下去，这颗 CPU 就停在你这一行代码上；症状不是清晰的报错，而是偶发的整机卡顿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>驱动的生命周期是骨架的主体。总线扫描发现设备，按标识匹配到驱动，调用 probe：映射设备的寄存器窗口、申请中断号并注册处理函数、初始化设备，最后把自己注册进某个子系统——块设备交出请求处理入口，字符设备交出文件操作表，网络设备交出收发包接口。remove 按相反顺序拆除。中断半程：设备拉线，控制器路由成向量，通用中断层查表调用驱动注册的顶半部——确认设备、取走数据或推进 DMA 描述符环、标记需要下半部，然后立刻返回。上半程注册、下半程查表，这两张表（设备表与中断表）就是整条异步路的索引。</p><p><span class="marginnote">术语翻译：probe 就是驱动的「自我介绍环节」——内核发现设备后喊一声「谁管它」，匹配上的驱动上前做三件事：把设备寄存器映射进地址空间、登记自己的中断处理函数、把自己挂进对应子系统；之后这台设备的所有事件，都沿这张登记表找回来。</span></p>',9)),(B(),s(i,null,{default:A(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUS%5B%22%E6%80%BB%E7%BA%BF%E6%89%AB%E6%8F%8F%E5%8F%91%E7%8E%B0%E8%AE%BE%E5%A4%87%22%5D%20--%3E%20MATCH%7B%22%E6%A0%87%E8%AF%86%E5%8C%B9%E9%85%8D%E5%88%B0%E9%A9%B1%E5%8A%A8%3F%22%7D%0A%20%20MATCH%20--%3E%7C%E6%98%AF%7C%20PROBE%5B%22probe%EF%BC%9A%E6%98%A0%E5%B0%84%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%8C%E7%94%B3%E8%AF%B7%E4%B8%AD%E6%96%AD%22%5D%0A%20%20PROBE%20--%3E%20REG%5B%22%E6%B3%A8%E5%86%8C%E8%BF%9B%E5%AD%90%E7%B3%BB%E7%BB%9F%EF%BC%9A%E5%9D%97%E3%80%81%E5%AD%97%E7%AC%A6%E6%88%96%E7%BD%91%E7%BB%9C%22%5D%0A%20%20IRQ%5B%22%E8%AE%BE%E5%A4%87%E6%8B%89%E4%B8%AD%E6%96%AD%E7%BA%BF%22%5D%20--%3E%20VEC%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%E8%B7%AF%E7%94%B1%E6%88%90%E5%90%91%E9%87%8F%22%5D%0A%20%20VEC%20--%3E%20TOP%5B%22%E9%A1%B6%E5%8D%8A%E9%83%A8%EF%BC%9A%E7%A1%AE%E8%AE%A4%E8%AE%BE%E5%A4%87%EF%BC%8C%E5%8F%96%E6%95%B0%E5%B9%B6%E6%A0%87%E8%AE%B0%E4%B8%8B%E5%8D%8A%E9%83%A8%22%5D%0A%20%20TOP%20--%3E%7C%E8%83%BD%E5%81%9A%E5%AE%8C%7C%20DONE%5B%22%E8%BF%94%E5%9B%9E%E8%A2%AB%E4%B8%AD%E6%96%AD%E7%9A%84%E7%8E%B0%E5%9C%BA%22%5D%0A%20%20TOP%20--%3E%7C%E9%9C%80%E8%A6%81%E6%9B%B4%E5%A4%9A%7C%20BOT%5B%22tasklet%20%E6%88%96%20workqueue%20%E6%94%B6%E5%B0%BE%22%5D%0A%20%20MATCH%20--%3E%7C%E5%90%A6%7C%20SKIP%5B%22%E8%AE%BE%E5%A4%87%E7%95%99%E5%9C%A8%E6%9C%AA%E9%A9%B1%E5%8A%A8%E7%8A%B6%E6%80%81%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("顶半部为什么必须短：它运行在中断上下文，当前中断线被屏蔽，它占多久，同类中断就压多久，实时性直接受损。可睡眠的收尾交给 workqueue——它运行在进程上下文，背后正是第一课讲的普通调度；不可睡眠但可延迟的用 tasklet。选择判据只有一个：这一步要不要睡眠。完成通知是骨架的接缝：驱动提交请求后在等待队列上睡眠，中断到达后完成唤醒——上一课的 read 阻塞语义就落在这条链上，"),a("a",{href:"/cs/tasklet-workqueue"},"tasklet 与 workqueue"),e(" 给的部件在这里咬合。锁的配规则也由此定：可能被中断抢走的共享数据，临界区里要配 "),a("a",{href:"/cs/lock-irq"},"锁与关中断"),e(" 的组合，漏配就产生只在负载高时出现的竞态。")],-1)),(B(),s(i,null,{default:A(()=>[o(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20JOB%5B%22%E4%B8%AD%E6%96%AD%E5%B8%A6%E6%9D%A5%E7%9A%84%E4%B8%80%E4%BB%B6%E6%94%B6%E5%B0%BE%E5%B7%A5%E4%BD%9C%22%5D%20--%3E%20Q1%7B%22%E5%87%A0%E5%BE%AE%E7%A7%92%E5%86%85%E8%83%BD%E5%81%9A%E5%AE%8C%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E8%83%BD%22%7C%20TOP%5B%22%E6%94%BE%E9%A1%B6%E5%8D%8A%E9%83%A8%3A%20%E4%B8%AD%E6%96%AD%E4%B8%8A%E4%B8%8B%E6%96%87%E7%AB%8B%E5%8D%B3%E5%81%9A%22%5D%0A%20%20Q1%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20Q2%7B%22%E8%BF%87%E7%A8%8B%E4%B8%AD%E9%9C%80%E8%A6%81%E7%9D%A1%E7%9C%A0%E5%90%97%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E4%B8%8D%E7%9D%A1%22%7C%20TL%5B%22tasklet%3A%20%E5%8F%AF%E5%BB%B6%E8%BF%9F%2C%20%E4%BB%8D%E6%98%AF%E4%B8%AD%E6%96%AD%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20Q2%20--%3E%7C%22%E8%A6%81%E7%9D%A1%22%7C%20WQ%5B%22workqueue%3A%20%E8%BF%9B%E7%A8%8B%E4%B8%8A%E4%B8%8B%E6%96%87%2C%20%E5%8F%AF%E7%9D%A1%E7%9C%A0%E5%8F%AF%E7%AD%89%E9%94%81%22%5D%0A%20%20TOP%20--%3E%20COST%5B%22%E9%A1%B6%E5%8D%8A%E9%83%A8%E6%9C%9F%E9%97%B4%E5%90%8C%E7%BA%BF%E4%B8%AD%E6%96%AD%E8%A2%AB%E5%B1%8F%E8%94%BD%3A%20%E8%B6%8A%E7%9F%AD%E8%B6%8A%E5%A5%BD%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">直觉类比：顶半部像急诊分诊台——只做「确认是谁、把人接进来」这几秒的事，马上腾出手接待下一位；化验和手术这类耗时又能等的活，转给后台的 workqueue 排队做。分诊台占多久，后面的急救车就堵多久——这就是「顶半部必须短」的全部理由。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>具体设备协议是各自课的对象——NVMe 的队列对在 <a href="/cs/nvme-driver">NVMe 队列与驱动</a>，本课只取它们的公共骨架；中断亲和与线程化中断（<a href="/cs/irq-affinity">中断亲和</a>、<a href="/cs/irq-thread">线程化中断</a>）在骨架上叠加策略，不重复；中断虚拟化是主干隔离单元的对象。也别把骨架当成唯一形态：轮询驱动的设备没有中断半程，DMA 完成 CPU 不介入——骨架描述的是中断驱动这一主导形态，其它形态是它的减法。</p><p><span class="marginnote">共享中断线上的每个处理函数都必须先读设备状态寄存器判断「是不是我的中断」，不是就返回未处理——误认邻居的中断会把别人的完成事件偷走，症状是两台设备都偶发卡死，这是共享线上最经典的驱动 bug。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>驱动的本质是 probe 里的一串注册：寄存器窗口、中断处理函数、子系统接口。</li><li>中断路径是「设备、控制器、通用层、顶半部」；顶半部只做确认与取数。</li><li>下半部的判据只有一个：要不要睡眠——要就 workqueue，不要才 tasklet。</li><li>阻塞 I/O 的语义落在等待队列加中断唤醒这条链上；关中断锁保护被抢的临界区。</li><li>出处：Tanenbaum and Bos, <em>Modern Operating Systems</em>；Arpaci-Dusseau, <em>OSTEP</em>；Love, <em>Linux Kernel Development</em>。</li></ul>',6))])}const T=n(p,[["render",d]]);export{f as __pageData,T as default};
